package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.*;import br.edu.ifms.robotica.model.*;import br.edu.ifms.robotica.seguranca.TokenUtil;import br.edu.ifms.robotica.util.EmailService;
@WebServlet("/esqueci-senha") public class EsqueciSenhaServlet extends HttpServlet{
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{p.setHeader("Cache-Control","no-store");r.getRequestDispatcher("/WEB-INF/views/public/esqueci-senha.jsp").forward(r,p);}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");try{String tipo=r.getParameter("tipo"),email=r.getParameter("email"),token=TokenUtil.gerar();Long eid=null,cid=null;if("estudante".equals(tipo)){Estudante e=new EstudanteDAO().buscarPorEmail(email);if(e!=null&&e.isAtivo())eid=e.getId();}else if("coordenador".equals(tipo)){Coordenador c=new CoordenadorDAO().buscarPorEmail(email);if(c!=null&&c.isAtivo())cid=c.getId();}if(eid!=null||cid!=null){new TokenRedefinicaoDAO().inserir(token,eid,cid);EmailService mail=new EmailService();mail.enviarRedefinicao(email,mail.baseUrl()+"/redefinir-senha?token="+URLEncoder.encode(token,StandardCharsets.UTF_8));}}catch(Exception e){getServletContext().log("Falha ao processar recuperação de senha (sem dados sensíveis).",e);}r.setAttribute("mensagem","senha.recuperacao.generica");doGet(r,p);}
}
